contracts/ApplicantManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "./libraries/Types.sol";

contract ApplicantManager{
//errors

error ApplicantAlreadyExists();

error ApplicantNotFound();

error CertificateAlreadyExists();

error CertificateNotFound();

error CertificateAlreadyRevoked();

error ProjectAlreadyExists();    

error ProjectNotFound();

error AlreadyVerifiedByIssuer();

error InvalidCredentialType();

error InvalidExpiry();

error ProjectVerificationAlreadyRevoked();

error VerificationNotFound();

error UnauthorisedOperation();

error RequestManagerAlreadySet();

error NotOwner();

error EmploymentAlreadyExists();

error EmploymentNotFound();

error EmploymentAlreadyTerminated();

error EmploymentManagerAlreadySet();


//events
event ApplicantCreated(address  indexed applicantaddress);

event CertificateAdded(address indexed student,bytes32 indexed certificateHash,address indexed issuer);

event CertificateRevoked(bytes32 indexed certificateHash, address indexed  issuer);

event Projectadded( address indexed student,bytes32 indexed  projectHash );

event Projectverified(address indexed verifier,bytes32 indexed projecthash);

 event ProjectVerificationRevoked(address indexed verifier,bytes32 indexed projectHash);

 event EmploymentAdded(address indexed student,bytes32 indexed employmentHash,address indexed organisation);

event EmploymentTerminated(bytes32 indexed employmentHash,address indexed organisation);


 //variables

address public employmentManager;
address public requestManager;
address public immutable owner;


//structs


struct Certificate {
    bytes32 certificateHash;
    Types.CredentialType credentialType;
    address issuer;
    uint64 issuedAt;
    uint64 expiresAt;
    bool revoked;
}

struct Project {
    bool exists;
    bytes32 projectHash;
    address owner;
    Types.Verification[] verifications;
}



struct Employment {
    bool exists;
    bytes32 employmentHash;
    address organisation;
    Types.EmploymentType employmentType;
    uint64 joinedAt;
    uint64 endedAt;
}



struct Applicant {
    bool exists;
    bytes32[] certificates;
    bytes32[] projects;
     bytes32[] employments;
}




//mapping

mapping(address=>Applicant) public applicants;

mapping(bytes32 => Certificate) public certificates;

mapping(bytes32 => Project) public projects;

mapping(bytes32 => Employment) public employments;

//modifier



modifier onlyOwner() {
    if (msg.sender != owner) revert NotOwner();
    _;
}
modifier onlyRequestManager(){
    if(msg.sender!=requestManager){
        revert UnauthorisedOperation();
    }
    _;
}
modifier onlyEmploymentManager(){
    if(msg.sender!=employmentManager){
        revert UnauthorisedOperation();
    }
    _;
}
//constructor

constructor() {
    owner = msg.sender;
}

//owner sets reqmanager
function setRequestManager(address _requestManager)
    external
    onlyOwner
{
    if (requestManager != address(0)) {
        revert RequestManagerAlreadySet();
    }

    requestManager = _requestManager;
}
//sets employmanager 
function setEmploymentManager(address _employmentManager) external onlyOwner {
    if (employmentManager != address(0)) revert EmploymentManagerAlreadySet();
    employmentManager = _employmentManager;
}



//applicant

//directly called by appllicant
function createApplicant() external {

    if(applicants[msg.sender].exists){
        revert ApplicantAlreadyExists();
    }

    applicants[msg.sender].exists = true;

    emit ApplicantCreated(msg.sender);
}


//certificate
function addCertificate(
    address student,
    bytes32 certificateHash,
    Types.CredentialType credentialType,
    address issuer,
    uint64 expiresAt
) external onlyRequestManager{

    if (!applicants[student].exists) {
        revert ApplicantNotFound();
    }

if (
    credentialType == Types.CredentialType.Project
) {
    revert InvalidCredentialType();
}


if (
    expiresAt != 0 &&
    expiresAt <= block.timestamp
){
        revert InvalidExpiry();
}


Certificate storage cert = certificates[certificateHash];

if (cert.issuer != address(0)) {
    revert CertificateAlreadyExists();
}


    certificates[certificateHash] = Certificate({
        certificateHash: certificateHash,
        credentialType: credentialType,
        issuer: issuer,
        issuedAt: uint64(block.timestamp),
        expiresAt: expiresAt,
        revoked: false
    });
    
    applicants[student].certificates.push(certificateHash);

    emit CertificateAdded(student,certificateHash,issuer);
}




function revokeCertificate(bytes32 certificateHash) external onlyRequestManager{

    Certificate storage cert = certificates[certificateHash];

    if (cert.issuer == address(0))
        revert CertificateNotFound();

    if (cert.revoked)
        revert CertificateAlreadyRevoked();

    cert.revoked = true;

    emit CertificateRevoked(certificateHash, cert.issuer);
}

//project


//addproject directly called by the applicant no req needed
function addProject(
    bytes32 projectHash
) external {
    address student=msg.sender;

    if (!applicants[student].exists) {
        revert ApplicantNotFound();
    }

    if (projects[projectHash].exists) {
        revert ProjectAlreadyExists();
    }

Project storage project = projects[projectHash];

project.exists = true;
project.projectHash = projectHash;
project.owner = student;
    applicants[student].projects.push(projectHash);

    emit Projectadded(student, projectHash);
}



function addProjectVerification(
    bytes32 projectHash,
    address verifier
) external onlyRequestManager{

    if (!projects[projectHash].exists) {
        revert ProjectNotFound();
    }

    Project storage project = projects[projectHash];

    for (uint256 i = 0; i < project.verifications.length; i++) {
        if (
            project.verifications[i].verifier == verifier &&
            !project.verifications[i].revoked
        ) {
            revert AlreadyVerifiedByIssuer();
        }
    }

    project.verifications.push(
        Types.Verification({
            verifier: verifier,
            verifiedAt: uint64(block.timestamp),
            revoked: false
        })
    );



    emit Projectverified(verifier,projectHash);
}


function revokeProjectVerification(
    bytes32 projectHash,
    address verifier
) external onlyRequestManager{

    if (!projects[projectHash].exists) {
        revert ProjectNotFound();
    }

    Project storage project = projects[projectHash];

    bool found = false;

    for (uint256 i = 0; i < project.verifications.length; i++) {

        if (project.verifications[i].verifier == verifier) {

            found = true;

            if (project.verifications[i].revoked) {
                revert ProjectVerificationAlreadyRevoked();
            }

            project.verifications[i].revoked = true;

            emit ProjectVerificationRevoked(
                verifier,
                projectHash
            );

            return;
        }
    }

    if (!found) {
        revert VerificationNotFound();
    }
}


//employment


function addEmployment(
    address student,
    bytes32 employmentHash,
    Types.EmploymentType employmentType,
    address organisation
) external onlyEmploymentManager {



if (!applicants[student].exists)
    revert ApplicantNotFound();

if (employments[employmentHash].exists)
    revert EmploymentAlreadyExists();



Employment storage employment = employments[employmentHash];

employment.exists = true;
employment.employmentHash = employmentHash;
employment.organisation = organisation;
employment.employmentType = employmentType;
employment.joinedAt = uint64(block.timestamp);

applicants[student].employments.push(employmentHash);

emit EmploymentAdded(student,employmentHash,organisation);

}

function endEmployment(bytes32 employmentHash) external onlyEmploymentManager{
Employment storage employment = employments[employmentHash];

if (!employment.exists)
    revert EmploymentNotFound();

if (employment.endedAt != 0)
    revert EmploymentAlreadyTerminated();

employment.endedAt = uint64(block.timestamp);

emit EmploymentTerminated(employmentHash,employment.organisation);
}


//getters
function isProjectVerified(bytes32 projectHash)
    public
    view
    returns (bool)
{
    if (!projects[projectHash].exists) {
    revert ProjectNotFound();
}
    Project storage project = projects[projectHash];

    for (uint256 i = 0; i < project.verifications.length; i++) {
        if (!project.verifications[i].revoked) {
            return true;
        }
    }

    return false;
}


function getProjectVerifications(
    bytes32 projectHash
)
    external
    view
    returns (Types.Verification[] memory)
{
    if (!projects[projectHash].exists) {
    revert ProjectNotFound();
}
    return projects[projectHash].verifications;
}

function getCertificates(address student)
    external
    view
    returns(bytes32[] memory){
        if (!applicants[student].exists) {
    revert ApplicantNotFound();
}
        return applicants[student].certificates;
    }


    function getProjects(address student)
    external
    view
    returns(bytes32[] memory){
         if (!applicants[student].exists) {
    revert ApplicantNotFound();
}

return applicants[student].projects;

    }


    function getEmployments(address student)
    external
    view
    returns (bytes32[] memory)
{
    if (!applicants[student].exists) {
        revert ApplicantNotFound();
    }

    return applicants[student].employments;
}
function isEmploymentActive(
    bytes32 employmentHash
)
    external
    view
    returns (bool)
{
    Employment storage employment = employments[employmentHash];

    if (!employment.exists)
        revert EmploymentNotFound();

    return employment.endedAt == 0;
}


//checking during login
    function applicantExists(address student)
    external
    view
    returns (bool)
{
    return applicants[student].exists;
}


}

contracts/EmploymentManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "./libraries/Types.sol";
import "./ApplicantManager.sol";
import "./OrganisationRegistry.sol";

contract EmploymentManager {

    //errors
    error OfferAlreadyExists(uint256 offerId);
    error OfferNotFound();
    error OfferAlreadyProcessed();
    error UnauthorizedStudent();
    error UnauthorizedOrganisation();
    error InvalidOrganisation();
    error EmploymentNotActive();
    error InvalidExpiry();
    error OfferExpired();

    //events
    event OfferCreated(uint256 indexed id, address indexed organisation, address indexed student);
    event OfferAccepted(uint256 indexed id);
    event OfferRejected(uint256 indexed id);
    event EmploymentEnded(uint256 indexed id);

    //constructor
    constructor(address applicantManagerAddress, address organisationRegistryAddress) {
        applicantManager = ApplicantManager(applicantManagerAddress);
        organisationRegistry = OrganisationRegistry(organisationRegistryAddress);
    }

    //struct
struct EmploymentOffer {
    uint256 id;
    bytes32 employmentHash;
    Types.EmploymentType employmentType;
    address organisation;
    address student;
    Types.RequestStatus status;
    bool active;
    uint64 offerDeadline;
}
    //statevars
    mapping(uint256 => EmploymentOffer) public offers;

    mapping(address => uint256[]) private organisationOffers;
    mapping(address => uint256[]) private studentOffers;

    // employmentHash -> organisation -> student -> offerId  (dedup, mirrors activeRequests)
    mapping(bytes32 => mapping(address => mapping(address => uint256)))
        public activeOffers;

    uint256 public nextOfferId;

    //contracts
    ApplicantManager public immutable applicantManager;
    OrganisationRegistry public immutable organisationRegistry;


    //functions

    // organisation initiates
function createOffer(
    bytes32 _employmentHash,
    Types.EmploymentType _employmentType,
    address _student,
    uint64 _offerDeadline
) external {

    if (activeOffers[_employmentHash][msg.sender][_student] != 0) {
        revert OfferAlreadyExists(
            activeOffers[_employmentHash][msg.sender][_student]
        );
    }

    if (!organisationRegistry.isActiveOrganisation(msg.sender)) {
        revert InvalidOrganisation();
    }

    if (_offerDeadline != 0 && _offerDeadline <= block.timestamp) {
        revert InvalidExpiry();
    }

    uint256 _id = ++nextOfferId;

    offers[_id] = EmploymentOffer({
        id: _id,
        employmentHash: _employmentHash,
        employmentType: _employmentType,
        organisation: msg.sender,
        student: _student,
        status: Types.RequestStatus.Pending,
        active: false,
        offerDeadline: _offerDeadline
    });

    organisationOffers[msg.sender].push(_id);
    studentOffers[_student].push(_id);

    activeOffers[_employmentHash][msg.sender][_student] = _id;

    emit OfferCreated(_id, msg.sender, _student);
}

   // internal: dedup / validity checks before accept/reject
function _validateOffer(uint256 offerId) internal view returns (EmploymentOffer storage offer) {

    offer = offers[offerId];

    if (offer.id == 0)
        revert OfferNotFound();

    if (offer.status != Types.RequestStatus.Pending)
        revert OfferAlreadyProcessed();

    if (offer.student != msg.sender)
        revert UnauthorizedStudent();

    if(offer.offerDeadline != 0 && offer.offerDeadline <= block.timestamp){
        revert OfferExpired(); 
    }

    return offer;
}

// internal: finalize status + clear active slot
function _closeOffer(
    EmploymentOffer storage offer,
    Types.RequestStatus status
) internal {

    offer.status = status;

    delete activeOffers[
        offer.employmentHash
    ][
        offer.organisation
    ][
        offer.student
    ];
}

// student accepts
function acceptOffer(uint256 offerId) external {

    EmploymentOffer storage offer = _validateOffer(offerId);


    offer.active = true;

    applicantManager.addEmployment(
        offer.student,
        offer.employmentHash,
        offer.employmentType,
        offer.organisation
    );

    _closeOffer(offer, Types.RequestStatus.Approved);

    emit OfferAccepted(offerId);
}

// student rejects
function rejectOffer(uint256 offerId) external {

    EmploymentOffer storage offer = _validateOffer(offerId);

    _closeOffer(offer, Types.RequestStatus.Rejected);

    emit OfferRejected(offerId);
}

// organisation ends an active employment (not a "revoke")
function endEmployment(uint256 offerId) external {

    EmploymentOffer storage offer = offers[offerId];

    if (offer.id == 0)
        revert OfferNotFound();

    if (offer.organisation != msg.sender)
        revert UnauthorizedOrganisation();

    if (!offer.active)
        revert EmploymentNotActive();

    offer.active = false;

    applicantManager.endEmployment(offer.employmentHash);

    emit EmploymentEnded(offerId);
}

//getters
function getOrganisationOffers() external view returns (uint256[] memory) {
    return organisationOffers[msg.sender];
}

function getStudentOffers() external view returns (uint256[] memory) {
    return studentOffers[msg.sender];
}

function isCurrentlyActive(uint256 offerId) external view returns (bool) {
    return offers[offerId].active;
}
}

