// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

library Types {

    enum CredentialType {
        Certificate,
        Project,
        Internship,
        Hackathon,
        ResearchPaper,
        Patent
    }

    enum RequestStatus {
        Pending,
        Approved,
        Rejected,
        Cancelled
    }

    struct Verification {
        address verifier;
        uint64 verifiedAt;
        bool revoked;
    }

enum RequestType {
    AddCertificate,
    RevokeCertificate,
    AddProjectVerification,
    RevokeProjectVerification,
    AddEmployment,
    TerminateEmployment
}
    
enum OrganizationType {
    Company,
    University,
    ResearchLab,
    NGO,
    Government,
    Other
}

enum EmploymentType {
    Internship,
    Employment
}
enum ApprovalType {
    Organisation,
    Student
}
}

contracts/OrganisationRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "./libraries/Types.sol";

contract OrganisationRegistry {

    //errors
    error OrganisationAlreadyRegistered();
    error OrganisationNotFound();
    error NotOwner();
    error InvalidAddress();

    //events
    event OrganisationRegistered(address indexed organisation, Types.OrganizationType organisationType);
    event OrganisationDeactivated(address indexed organisation);
    event OrganisationReactivated(address indexed organisation);

    //struct
    struct Organisation {
        bool exists;
        bool isActive;
        Types.OrganizationType organisationType;
    }

    //statevars
    mapping(address => Organisation) public organisations;

    address public immutable owner;

    //constructor
    constructor() {
        owner = msg.sender;
    }

    //modifiers
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    //functions
    function registerOrganisation(
        address _organisationAddress,
    
        Types.OrganizationType _organisationType
    ) external onlyOwner {

        if (_organisationAddress == address(0)) revert InvalidAddress();

        if (organisations[_organisationAddress].exists) {
            revert OrganisationAlreadyRegistered();
        }

        organisations[_organisationAddress] = Organisation({
            exists: true,
            isActive: true,
            organisationType: _organisationType
        });

        emit OrganisationRegistered(_organisationAddress, _organisationType);
    }

    function deactivateOrganisation(address _organisationAddress) external onlyOwner {

        Organisation storage organisation = organisations[_organisationAddress];

        if (!organisation.exists) revert OrganisationNotFound();

        organisation.isActive = false;

        emit OrganisationDeactivated(_organisationAddress);
    }

    function reactivateOrganisation(address _organisationAddress) external onlyOwner {

        Organisation storage organisation = organisations[_organisationAddress];

        if (!organisation.exists) revert OrganisationNotFound();

        organisation.isActive = true;

        emit OrganisationReactivated(_organisationAddress);
    }

    //view helper for other contracts (e.g. RequestManager) to check validity
    function isActiveOrganisation(address _organisationAddress) external view returns (bool) {
        return organisations[_organisationAddress].isActive;
    }


}

contracts/RequestManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;
import "./libraries/Types.sol";
import "./ApplicantManager.sol";
import "./OrganisationRegistry.sol";

contract RequestManager {

    //errors
    error RequestAlreadyExists(uint256 requestId);
    error RequestNotFound();
    error RequestAlreadyProcessed();
    error UnauthorizedVerifier();
    error InvalidExpiry();
    error InvalidRequestType();
    error InvalidIssuer();

    //events
    event RequestCreated(uint256 indexed id, address indexed student);
    event RequestApproved(uint256 indexed id);
    event RequestRejected(uint256 indexed id);

    //constructor
    constructor(address applicantManagerAddress,address orgRegistryaddress) {
        applicantManager = ApplicantManager(applicantManagerAddress);
        organisationRegistry= OrganisationRegistry(orgRegistryaddress);
    }

    //struct
    struct Request {
        uint256 id;
        bytes32 credentialHash;
        Types.CredentialType credentialType;
        Types.RequestType requestType;
        address student;
        address expectedVerifier;
        Types.RequestStatus status;
        uint64 createdAt;
        uint64 expiresAt;
    }

    //statevars
    mapping(uint256 => Request) public requests;


mapping(address => uint256[]) private outgoingRequests;
mapping(address => uint256[]) private incomingRequests;

    // credentialHash -> expectedVerifier -> requestType -> requestId
    mapping(bytes32 => mapping(address => mapping(Types.RequestType => uint256)))
        public activeRequests;

    uint256 public nextRequestId;

//contracts
    ApplicantManager public immutable applicantManager;
    OrganisationRegistry public immutable organisationRegistry;

    //functions
    function createRequest(
        bytes32 _credentialHash,
        Types.CredentialType _credentialType,
        Types.RequestType _requestType,
        address _expectedVerifier,
        uint64 _expiresAt
    ) external {

        if (activeRequests[_credentialHash][_expectedVerifier][_requestType] != 0) {
            revert RequestAlreadyExists(
                activeRequests[_credentialHash][_expectedVerifier][_requestType]
            );
        }

        _validateRequestType(_credentialType, _requestType);

        if (
            _requestType == Types.RequestType.AddCertificate &&
            _expiresAt != 0 &&
            _expiresAt <= block.timestamp
        ) {
            revert InvalidExpiry();
        }
        if (!organisationRegistry.isActiveOrganisation(_expectedVerifier)) {
            revert InvalidIssuer();
        }

        uint256 _id = ++nextRequestId;

        requests[_id] = Request({
            id: _id,
            student: msg.sender,
            expectedVerifier: _expectedVerifier,
            credentialHash: _credentialHash,
            credentialType: _credentialType,
            requestType: _requestType,
            status: Types.RequestStatus.Pending,
            createdAt: uint64(block.timestamp),
            expiresAt: _expiresAt
        });

outgoingRequests[msg.sender].push(_id);
incomingRequests[_expectedVerifier].push(_id);

        activeRequests[_credentialHash][_expectedVerifier][_requestType] = _id;

        emit RequestCreated(_id, msg.sender);
    }

    //makes sure the requestType actually matches the credentialType being acted on
    function _validateRequestType(
        Types.CredentialType credentialType,
        Types.RequestType requestType
    ) internal pure {

        if (credentialType == Types.CredentialType.Project) {

            if (
                requestType != Types.RequestType.AddProjectVerification &&
                requestType != Types.RequestType.RevokeProjectVerification
            ) {
                revert InvalidRequestType();
            }

        } else {

            if (
                requestType != Types.RequestType.AddCertificate &&
                requestType != Types.RequestType.RevokeCertificate
            ) {
                revert InvalidRequestType();
            }
        }
    }

    //validation (read-only, no side effects)
    function _validateRequest(
        uint256 requestId
    ) internal view returns (Request storage request) {

        request = requests[requestId];

        if (request.id == 0)
            revert RequestNotFound();

        if (request.status != Types.RequestStatus.Pending)
            revert RequestAlreadyProcessed();

        if (request.expectedVerifier != msg.sender)
            revert UnauthorizedVerifier();

        return request;
    }

    //closes out a request: sets final status and clears the active-request slot
    function _closeRequest(
        Request storage request,
        Types.RequestStatus status
    ) internal {

        request.status = status;

        delete activeRequests[
            request.credentialHash
        ][
            request.expectedVerifier
        ][
            request.requestType
        ];
    }

    function approveRequest(uint256 requestId) external {

        Request storage request = _validateRequest(requestId);

        if (request.requestType == Types.RequestType.AddCertificate) {

            _approveCertificate(request);

        } else if (request.requestType == Types.RequestType.RevokeCertificate) {

            _revokeCertificate(request);

        } else if (request.requestType == Types.RequestType.AddProjectVerification) {

            _approveProjectVerification(request);

        } else if (request.requestType == Types.RequestType.RevokeProjectVerification) {

            _revokeProjectVerification(request);

        } else {

            revert InvalidRequestType();
        }

        _closeRequest(request, Types.RequestStatus.Approved);

        emit RequestApproved(requestId);
    }

    function rejectRequest(uint256 requestId) external {
        Request storage request = _validateRequest(requestId);

        _closeRequest(request, Types.RequestStatus.Rejected);

        emit RequestRejected(requestId);
    }

    // ApplicantManager dispatch
    //internal function
    function _approveCertificate(
        Request storage request
    ) internal {

        applicantManager.addCertificate(
            request.student,
            request.credentialHash,
            request.credentialType,
            msg.sender,
            request.expiresAt
        );
    }

    function _revokeCertificate(
        Request storage request
    ) internal {

        applicantManager.revokeCertificate(
            request.credentialHash
        );
    }

    function _approveProjectVerification(
        Request storage request
    ) internal {

        applicantManager.addProjectVerification(
            request.credentialHash,
            msg.sender
        );
    }

    function _revokeProjectVerification(
        Request storage request
    ) internal {

        applicantManager.revokeProjectVerification(
            request.credentialHash,
            msg.sender
        );
    }
function getIssuerRequests()
    external
    view
    returns (uint256[] memory)
{
  
    return incomingRequests[msg.sender];
}

function getStudentRequests()
    external
    view
    returns (uint256[] memory)
{
    return outgoingRequests[msg.sender];
}




}

